package com.hsicen.a02_sampleimport androidx.activity.ComponentActivityimport androidx.compose.animation.animateColorAsStateimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.material.Textimport androidx.compose.runtime.*import androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.graphics.Color/******====== 1.2.声明式UI ======******//** * 声明式UI *   1.关键在于只需要声明，而不是界面看起来像声明. *   2.或者说不需要命令式更新 */@Composablefun ComponentActivity.stateScreen021() {  var name by remember { mutableStateOf("hsicen") }  val color by animateColorAsState(Color.Green)  Box(    contentAlignment = Alignment.Center,    modifier = Modifier.fillMaxSize()  ) {    Text(name, color = color)  }}